type Person = { id: number; links: Person[] };

function cloneContacts(start: Person | null): Person | null {
  // Return a deep copy of start: new objects for every reachable person,
  // same ids, same link order, no references back into the original.
  return start;
}

// Test harness: build linked people from an adjacency list, clone person 0,
// then read the copy back as an adjacency list.
function cloneContactsFrom(adj: number[][]): number[][] | string {
  if (adj.length === 0) return cloneContacts(null) === null ? [] : "expected null for an empty graph";
  const people: Person[] = adj.map((_, id) => ({ id, links: [] }));
  adj.forEach((ns, id) => { for (const n of ns) people[id].links.push(people[n]); });
  const originals = new Set<Person>(people);
  const copy = cloneContacts(people[0]);
  if (!copy) return "returned null";
  const seen = new Map<number, Person>();
  const queue: Person[] = [copy];
  seen.set(copy.id, copy);
  for (let head = 0; head < queue.length; head++) {
    const p = queue[head];
    if (originals.has(p)) return "the copy shares a node with the original";
    for (const f of p.links) {
      const known = seen.get(f.id);
      if (known && known !== f) return "two different copies of person " + f.id;
      if (!known) { seen.set(f.id, f); queue.push(f); }
    }
  }
  const out: number[][] = [];
  for (const [id, p] of [...seen].sort((x, y) => x[0] - y[0])) out[id] = p.links.map((f) => f.id);
  return out;
}

